let v40Expenses=[];
function expenseOption(value,label,current){return `<option value="${escapeHtml(value)}" ${String(value)===String(current)?'selected':''}>${escapeHtml(label)}</option>`;}
function newExpenseDefault(){
 const n=v40Expenses.length+1,baseAge=Math.max(0,Math.round(num('aRet',num('aAge',53)+5)));
 return {id:'exp-'+Date.now()+'-'+Math.random().toString(36).slice(2,7),name:'New expense '+n,category:'Other',type:'one-time',timing:'age',start:baseAge,end:baseAge,interval:10,dollars:'today',inflation:true,funding:'strategy',notes:'',enabled:true,stress:true,amountMode:'fixed',amount:50000,min:25000,max:75000,probability:.10,endProbability:.10,ageProbability:false,gap:1,maxOccurrences:0};
}
function expenseCardHtml(e,k){
 const isCont=e.type==='contingency',isRecurring=e.type==='recurring';
 const categoryOptions=ExpenseEngine.categories.map(x=>expenseOption(x,x,e.category)).join('');
 const typeOptions=[['one-time','Known one-time'],['recurring','Recurring replacement'],['contingency','Random contingency']].map(x=>expenseOption(x[0],x[1],e.type)).join('');
 const timingOptions=[['age','Person A age'],['year','Calendar year']].map(x=>expenseOption(x[0],x[1],e.timing)).join('');
 const dollarsOptions=[['today',"Today's dollars"],['future','First-occurrence dollars']].map(x=>expenseOption(x[0],x[1],e.dollars)).join('');
 const fundingOptions=[['strategy','Follow household strategy'],['balanced','Non-reg first'],['rrsp','RRSP first'],['corp','Corporation first'],['tfsa','TFSA first']].map(x=>expenseOption(x[0],x[1],e.funding)).join('');
 return `<div class="expense-card" data-expense-index="${k}">
   <div class="expense-card-head"><div class="expense-card-title" data-expense-title>Expense ${k+1}: ${escapeHtml(e.name||'Unnamed')}</div><div><label class="inline" style="display:inline-flex;font-size:10px"><input type="checkbox" data-expense-field="enabled" ${e.enabled?'checked':''}> Enabled</label> <button class="btn small-btn" type="button" data-remove-expense="${k}">Remove</button></div></div>
   <div class="formgrid three"><div><label>Name</label><input data-expense-field="name" value="${escapeHtml(e.name||'')}"></div><div><label>Category</label><select data-expense-field="category">${categoryOptions}</select></div><div><label>Type</label><select data-expense-field="type">${typeOptions}</select></div></div>
   <div class="formgrid three"><div><label>Amount</label><input data-expense-field="amount" type="number" min="0" value="${Number(e.amount||0)}" ${isCont&&e.amountMode==='range'?'disabled':''}></div><div><label>Timing basis</label><select data-expense-field="timing">${timingOptions}</select></div><div><label>${e.timing==='year'?'Calendar year':'Person A age'} — start / occurrence</label><input data-expense-field="start" type="number" value="${Number(e.start||0)}"></div></div>
   <div class="formgrid three"><div><label>End (inclusive)</label><input data-expense-field="end" type="number" value="${Number(e.end??e.start??0)}" ${e.type==='one-time'?'disabled':''}></div><div><label>Every N years</label><input data-expense-field="interval" type="number" min="1" value="${Number(e.interval||10)}" ${isRecurring?'':'disabled'}></div><div><label>Dollar basis</label><select data-expense-field="dollars" ${isCont?'disabled':''}>${dollarsOptions}</select></div></div>
   <div class="formgrid three"><div><label>Funding preference</label><select data-expense-field="funding">${fundingOptions}</select></div><div><label>Inflation-adjust cost?</label><select data-expense-field="inflation">${expenseOption('yes','Yes',e.inflation?'yes':'no')}${expenseOption('no','No',e.inflation?'yes':'no')}</select></div><div><label>Apply expense stress multiplier?</label><select data-expense-field="stress">${expenseOption('yes','Yes',e.stress?'yes':'no')}${expenseOption('no','No',e.stress?'yes':'no')}</select></div></div>
   ${isCont?`<details><summary>Advanced contingency options</summary><div class="formgrid three"><div><label>Amount mode</label><select data-expense-field="amountMode">${expenseOption('fixed','Fixed amount',e.amountMode)}${expenseOption('range','Random range',e.amountMode)}</select></div><div><label>Minimum amount</label><input data-expense-field="min" type="number" min="0" value="${Number(e.min||0)}"></div><div><label>Maximum amount</label><input data-expense-field="max" type="number" min="0" value="${Number(e.max||0)}"></div></div><div class="formgrid three"><div><label>Annual chance at start %</label><input data-expense-field="probability" type="number" min="0" max="100" step="0.1" value="${(Number(e.probability||0)*100).toFixed(1)}"></div><div><label>Annual chance at end %</label><input data-expense-field="endProbability" type="number" min="0" max="100" step="0.1" value="${(Number(e.endProbability??e.probability??0)*100).toFixed(1)}"></div><div><label>Probability changes with age?</label><select data-expense-field="ageProbability">${expenseOption('no','No',e.ageProbability?'yes':'no')}${expenseOption('yes','Yes — interpolate start to end',e.ageProbability?'yes':'no')}</select></div></div><div class="formgrid"><div><label>Minimum years between occurrences</label><input data-expense-field="gap" type="number" min="0" value="${Number(e.gap||0)}"></div><div><label>Maximum occurrences (0 = unlimited)</label><input data-expense-field="maxOccurrences" type="number" min="0" value="${Number(e.maxOccurrences||0)}"></div></div><div class="field-help">Random contingencies use a separate deterministic random stream, so they do not change the underlying market-return paths. Contingencies always use today's-dollar amounts.</div></details>`:''}
  </div>`;
}
function renderExpenseList(){const host=$('expenseList');if(!host)return;if(!v40Expenses.length){host.innerHTML='<div class="expense-empty">No additional irregular expenses yet. Click <strong>+ Add expense</strong> to create the first one.</div>';return;}host.innerHTML=v40Expenses.map(expenseCardHtml).join('');}
function escapeHtml(v){return String(v??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));}
function addExpenseItem(){v40Expenses.push(newExpenseDefault());renderExpenseList();invalidateResults();const cards=$('expenseList')?.querySelectorAll('.expense-card');cards?.[cards.length-1]?.scrollIntoView?.({behavior:'smooth',block:'nearest'});}
function updateExpenseField(el){
 const card=el.closest('[data-expense-index]');if(!card)return;const idx=Number(card.dataset.expenseIndex),e=v40Expenses[idx];if(!e)return;const f=el.dataset.expenseField;if(!f)return;
 const integerFields=new Set(['start','end','interval','gap','maxOccurrences']);const numberFields=new Set(['amount','min','max']);const probabilityFields=new Set(['probability','endProbability']);
 if(f==='enabled')e.enabled=el.checked;
 else if(f==='inflation')e.inflation=el.value==='yes';
 else if(f==='stress')e.stress=el.value==='yes';
 else if(f==='ageProbability')e.ageProbability=el.value==='yes';
 else if(probabilityFields.has(f))e[f]=clamp((parseFloat(el.value)||0)/100,0,1);
 else if(integerFields.has(f))e[f]=Math.round(parseFloat(el.value)||0);
 else if(numberFields.has(f))e[f]=Math.max(0,parseFloat(el.value)||0);
 else e[f]=el.value;
 if(f==='start'&&e.type==='one-time')e.end=e.start;
 if(f==='type'){
   if(e.type==='one-time')e.end=e.start;
   if(e.type==='contingency')e.dollars='today';
 }
 if(f==='name'){const t=card.querySelector('[data-expense-title]');if(t)t.textContent='Expense '+(idx+1)+': '+(e.name||'Unnamed');}
 if(f==='amount'&&e.amountMode==='fixed'){e.min=e.amount;e.max=e.amount;}
 if(f==='min'&&e.max<e.min)e.max=e.min;
 if(f==='max'&&e.max<e.min)e.min=e.max;
 invalidateResults();
 if(['type','timing','amountMode'].includes(f))renderExpenseList();
}
function updateReportExportState(){const b=$('exportReportBtn');if(!b)return;const ready=!!lastSimulationResult;b.disabled=!ready;b.title=ready?'Export the completed simulation report as PDF':'Run the simulation first';b.textContent=ready?'Export Full Report PDF':'Export Full Report PDF';}
function invalidateResults(){window.invalidateOptimizer?.();lastSimulationResult=null;lastAllocationRows=null;representativePaths=null;lastDecisionSupport=null;lastScenarioComparison=null;$('decisionSupportStatus')&&($('decisionSupportStatus').textContent='Inputs changed — rerun simulation.');updateReportExportState();}

