function validate(i){const e=[];if(i.A.ret<i.A.age)e.push('Person A retirement age must be at least current age.');if(i.A.ret>=i.planAge)e.push('Person A retirement age must be below the planning age.');if(i.planAge<=i.A.age)e.push('Planning age must exceed Person A current age.');if(i.couple&&i.B.ret<i.B.age)e.push('Person B retirement age must be at least current age.');for(const [n,v] of Object.entries({spending:i.spend,corp:i.corp,A_RRSP:i.A.rrsp,A_TFSA:i.A.tfsa,A_NR:i.A.nr}))if(v<0)e.push(n+' cannot be negative.');if(i.calculationVersion==="v4.0.3"&&(i.A.acb>i.A.nr||i.B.acb>i.B.nr||i.corpACB>i.corp))e.push('An ACB is above its account FMV. Correct the ACB or FMV.');if(i.corpAddUntil<i.A.age)e.push('Corporate addition stop age cannot be below Person A current age.');if(i.corpAddUntil>i.planAge)e.push('Corporate addition stop age cannot exceed the planning age.');if(i.A.rrifAge<18||i.A.rrifAge>71)e.push('Person A RRIF conversion age must be between 18 and 71 (past conversion is allowed).');if(i.couple&&(i.B.rrifAge<18||i.B.rrifAge>71))e.push('Person B RRIF conversion age must be between 18 and 71 (past conversion is allowed).');if(i.passiveStop<=i.passiveStart)e.push('Passive-income stop age must be above its start age.');if(i.passiveOwnerA<0||i.passiveOwnerA>1)e.push('Passive-income Person A ownership must be between 0% and 100%.');if(i.essentialFloor<.10||i.essentialFloor>1)e.push('Essential-lifestyle floor must be between 10% and 100%.');if(i.maxDrop<.05||i.maxDrop>.95)e.push('Extreme 1-year loss limit must be between 5% and 95%.');if(i.maxGain<.20||i.maxGain>1.50)e.push('Extreme 1-year gain limit must be between 20% and 150%.');if(i.mode==='historical'&&(i.histStart<1900||i.histEnd>2025||i.histStart>i.histEnd))e.push('Historical start years must be between 1900 and 2025, with first year no later than last year.');e.push(...ExpenseEngine.validateExpenses(i));return e}

