function renderHistoricalTable(r){const box=$('historicalResults'),host=$('historicalTable');if(r.mode!=='historical'){box.classList.add('hidden');host.innerHTML='';return}box.classList.remove('hidden');let h='<table style="width:100%;border-collapse:collapse;font-size:12px"><thead><tr><th style="text-align:left;padding:6px;border-bottom:1px solid #38506e">Retirement start</th><th style="padding:6px;border-bottom:1px solid #38506e">Flexible</th><th style="padding:6px;border-bottom:1px solid #38506e">Full target</th><th style="padding:6px;border-bottom:1px solid #38506e">Severe?</th><th style="text-align:right;padding:6px;border-bottom:1px solid #38506e">Min lifestyle</th><th style="text-align:right;padding:6px;border-bottom:1px solid #38506e">Max annual cut</th><th style="padding:6px;border-bottom:1px solid #38506e">Depleted?</th><th style="text-align:right;padding:6px;border-bottom:1px solid #38506e">After-tax ending</th><th style="text-align:right;padding:6px;border-bottom:1px solid #38506e">Historical yrs</th><th style="text-align:right;padding:6px;border-bottom:1px solid #38506e">Random tail yrs</th></tr></thead><tbody>';for(const x of r.historicalRows){h+=`<tr><td style="padding:5px;border-bottom:1px solid rgba(56,80,110,.35)">${x.year}</td><td style="text-align:center">${x.flex?'✓':'✕'}</td><td style="text-align:center">${x.full?'✓':'✕'}</td><td style="text-align:center">${x.severe?'Yes':'No'}</td><td style="text-align:right">${pct(x.minLifestyle)}</td><td style="text-align:right">${money(x.maxCut)}</td><td style="text-align:center">${x.depleted?('Yes @ '+Math.round(x.depletionAge)):'No'}</td><td style="text-align:right">${money(x.afterTax)}</td><td style="text-align:right">${x.histYears}</td><td style="text-align:right">${x.randomYears}</td></tr>`}h+='</tbody></table>';host.innerHTML=h}
