function riskPct(x){if(!Number.isFinite(x))return '--';if(x===0)return '0%';if(x<.1)return '<0.1%';return x.toFixed(1)+'%';}
function extremeSub(m,span=1){if(!m)return 'Personal portfolio';const age=span===1?`age ${Math.round(m.ageStart)}`:`ages ${Math.round(m.ageStart)}–${Math.round(m.ageEnd)}`;const yr=m.calYear?` • year ${m.calYear}`:'';return `${age}${yr} • ${m.pathLabel}`;}
function renderReturnDiagnostics(r){const d=r.returnDiag||{},shownWorst=Number.isFinite(r.badDecileWorst1)?r.badDecileWorst1:d.worst1,shownBest=Number.isFinite(r.goodDecileBest1)?r.goodDecileBest1:d.best1;setKpi('kWorst1',signedPct(shownWorst),'bad');setKpi('kBest1',signedPct(shownBest),'good');setKpi('kWorst3',signedPct(d.worst3),'bad');setKpi('kBest3',signedPct(d.best3),'good');const absWorst=Number.isFinite(d.worst1)?(d.worst1*100).toFixed(2)+'%':'--',absBest=Number.isFinite(d.best1)?(d.best1*100).toFixed(2)+'%':'--';$('kWorst1Sub').textContent=`Only 10% of paths had a worse single year • absolute worst ${absWorst}`;$('kBest1Sub').textContent=`Only 10% of paths had a better single year • absolute best ${absBest}`;$('kWorst3Sub').textContent=extremeSub(d.worst3Meta,3);$('kBest3Sub').textContent=extremeSub(d.best3Meta,3);const seed=`seed ${r.i.seed}`,lossPct=((r.i.maxDrop||.95)*100).toFixed(0),gainPct=((r.i.maxGain||1.5)*100).toFixed(0),lowCross=d.boundaryExceedances||0,highCross=d.upperBoundaryExceedances||0,rawWorst=Number.isFinite(d.worstRaw)?signedPct(d.worstRaw):'--',rawBest=Number.isFinite(d.bestRaw)?signedPct(d.bestRaw):'--';const modeText=r.mode==='historical'?'Historical proxy years are unaltered; only randomized tail years use the return limits':'Monte Carlo randomized returns use smooth downside and upside tail compression, not hard clamps';$('returnDiagSub').textContent=`${modeText} • ${d.totalYears?.toLocaleString?.()||0} portfolio-years • loss limit −${lossPct}% / gain limit +${gainPct}% • raw draws beyond loss limit ${lowCross.toLocaleString()} / gain limit ${highCross.toLocaleString()} • raw range ${rawWorst} to ${rawBest} • ${seed}.`;}
function decisionStatus(r){const p10End=percentile(r.ends,.10),annual=Math.max(1,r.i.spend);if(r.full>=98&&r.severeRisk<=1&&r.depletion<=1&&p10End>=annual*8)return {label:'Potentially overfunded',cls:'blue'};if(r.full>=90&&r.flex>=95&&r.severeRisk<=2&&r.depletion<=5)return {label:'Strong / resilient',cls:'good'};if(r.flex>=90&&r.severeRisk<=5&&r.depletion<=10)return {label:'Comfortable with adjustments',cls:'good'};if(r.flex>=80&&r.severeRisk<=15)return {label:'Watch / optimize',cls:'warn'};return {label:'Vulnerable — changes needed',cls:'bad'};}
function renderDecisionDashboard(r){const s=decisionStatus(r),badge=$('planStatus');badge.textContent=s.label;badge.className='status-badge '+s.cls;const p10Floor=percentile(r.lifestyleFloors||[],.10),p90Cut=percentile(r.maxRealCuts||[],.90),p10End=percentile(r.ends,.10),p10RealEnd=percentile(r.realEnds||[],.10),medTax=percentile(r.taxes,.50),floorPct=(r.i.essentialFloor*100).toFixed(0),floorToday=r.i.spend*r.i.essentialFloor,typicalYears=percentile(r.yearsBelowTarget||[],.50),cuts=(r.avgCutsWhenNeeded||[]).filter(x=>x>1),typicalCut=cuts.length?percentile(cuts,.50):0,essentialMaintained=100-r.severeRisk,portfolioSurvival=100-r.depletion;
 setKpi('kSevere',riskPct(r.severeRisk),r.severeRisk<=2?'good':r.severeRisk<=10?'warn':'bad');$('kSevereSub').textContent=`${(r.severeCount||0).toLocaleString()} of ${r.i.sims.toLocaleString()} paths • below ${floorPct}% (${money(floorToday)}/yr today $)`;setKpi('kLifestyleP10',pct(p10Floor),p10Floor>=90?'good':p10Floor>=r.i.essentialFloor*100?'warn':'bad');setKpi('kCutP90',money(p90Cut),p90Cut<=r.i.spend*.10?'good':p90Cut<=r.i.spend*(1-r.i.essentialFloor)?'warn':'bad');
 const lp=$('lifestylePlain');if(lp)lp.innerHTML=`<div class="lifestyle-item"><div class="l">Planned lifestyle</div><div class="v">${money(r.i.spend)}/yr</div><div class="muted-note">today's dollars</div></div><div class="lifestyle-item"><div class="l">Essential lifestyle floor</div><div class="v">${money(floorToday)}/yr</div><div class="muted-note">maintained in ${essentialMaintained.toFixed(1)}% of paths</div></div><div class="lifestyle-item"><div class="l">Typical years with cuts</div><div class="v">${typicalYears.toFixed(1)}</div><div class="muted-note">median across paths</div></div><div class="lifestyle-item"><div class="l">Typical reduction when cuts occur</div><div class="v">${money(typicalCut)}/yr</div><div class="muted-note">median average cut among paths that cut spending</div></div>`;
 let summary=`<strong>${s.label}.</strong> The original planned lifestyle is maintained without guardrail reductions in <strong>${r.full.toFixed(1)}%</strong> of paths. The flexible policy is successfully funded in <strong>${r.flex.toFixed(1)}%</strong>, but that figure allows spending reductions and therefore is <strong>not</strong> the probability of maintaining the original spending target. At least the essential lifestyle floor (${money(floorToday)}/yr real) is maintained in <strong>${essentialMaintained.toFixed(1)}%</strong>. The portfolio avoids depletion in <strong>${portfolioSurvival.toFixed(1)}%</strong>. Worst-decile maximum annual reduction is about <strong>${money(p90Cut)}</strong> in today's dollars. P10 ending after-tax value is <strong>${money(p10End)}</strong> (≈ <strong>${money(p10RealEnd)}</strong> today).`;
 if(r.full>=98&&r.severeRisk<=1&&r.depletion<=1)summary+=' The model is signaling that maximizing the success percentage is probably less useful than testing whether you can spend or gift more.';else if(r.severeRisk>10)summary+=' The magnitude of bad outcomes is material, so reducing the base commitment or adding a contingency rule deserves priority.';else if(r.flex-r.full>=8)summary+=' The large gap between full and flexible success means guardrail adjustments are doing meaningful work; the plan survives much more often than it delivers the original lifestyle unchanged.';else summary+=' Focus on the size and duration of required adjustments rather than chasing a one-point change in the headline probability.';$('decisionSummary').innerHTML=summary;
 let spendAction;if(r.full>=98&&r.severeRisk<=1&&r.depletion<=1)spendAction=`Test a second scenario with recurring spending 10% higher (${money(r.i.spend*1.10)}/yr today $), or add a discretionary travel/gifting budget.`;else if(r.full>=90)spendAction=`Keep ${money(r.i.spend)}/yr as the baseline, then test +5% and +10% spending. Watch severe-shortfall risk and years with cuts.`;else if(r.flex>=95&&r.severeRisk<=2)spendAction=`The portfolio usually survives and essential spending is protected, but the full lifestyle often requires cuts. Decide whether those discretionary reductions are acceptable.`;else spendAction=`Test a 5–10% lower recurring target and, separately, a later retirement age. Compare how much each change improves severe-shortfall risk and the bad-decile lifestyle floor.`;
 let riskAction;if(r.severeRisk<=2)riskAction=`Your essential-lifestyle floor is rarely breached. Define in advance which discretionary categories get cut first and which large purchases are deferred after a major decline.`;else if(r.severeRisk<=10)riskAction=`Check whether ${money(floorToday)}/yr truly represents household essentials. The severe-shortfall result is only as meaningful as that floor.`;else riskAction=`Severe-shortfall risk is high enough to justify structural changes before fine-tuning allocation.`;
 const rrsp=r.i.A.rrsp+r.i.B.rrsp,corp=r.i.corp;let taxAction=`Median modeled lifetime tax is ${money(medTax)}. v4.0 compares Balanced, RRSP Melt and Corporate First using paired paths and judges tax together with downside retirement outcomes.`;if(rrsp>1000000||corp>1000000)taxAction+=` Starting RRSP/RRIF (${money(rrsp)}) and corporate assets (${money(corp)}) make withdrawal sequencing particularly relevant.`;$('actionSpend').textContent=spendAction;$('actionRisk').textContent=riskAction;$('actionTax').textContent=taxAction;}

function render(r){const p=r.flex/100,se=1.96*Math.sqrt(Math.max(.000001,p*(1-p)/r.i.sims))*100;setKpi('kFlex',pct(r.flex),r.flex>=90?'good':r.flex>=80?'warn':'bad');setKpi('kFull',pct(r.full),r.full>=90?'good':r.full>=80?'warn':'bad');setKpi('kDeplete',riskPct(r.depletion),r.depletion<=5?'good':r.depletion<=15?'warn':'bad');$('kDepleteSub').textContent=`${(r.depleteCount||0).toLocaleString()} of ${r.i.sims.toLocaleString()} paths • assets ≤ $1,000`;setKpi('kP10',money(percentile(r.ends,.10)),'warn');setKpi('kP50',money(percentile(r.ends,.50)),'blue');setKpi('kTax',money(percentile(r.taxes,.50)),'purple');$('kP10Sub').textContent=`≈ ${money(percentile(r.realEnds||[],.10))} in today's dollars`;$('kP50Sub').textContent=`≈ ${money(percentile(r.realEnds||[],.50))} in today's dollars`;$('kTaxSub').textContent=`≈ ${money(percentile(r.realTaxes||[],.50))} today-dollar cumulative`;renderDecisionDashboard(r);renderRepresentativePaths(r);renderReturnDiagnostics(r);$('kFlexSub').textContent=r.mode==='historical'?`${r.i.sims} retirement start years tested`:`95% sampling band ≈ ±${se.toFixed(1)} pts`;drawFan(r);drawHist(r);drawRisk(r);const med=percentile(r.ends,.5),p10=percentile(r.ends,.1),medReal=percentile(r.realEnds||[],.5),p10Real=percentile(r.realEnds||[],.1),p10Floor=percentile(r.lifestyleFloors||[],.10),p90Cut=percentile(r.maxRealCuts||[],.90);let text;if(r.mode==='historical'){text=`Historical / Hybrid mode tested <strong>${r.i.sims}</strong> retirement start years from <strong>${r.i.histStart}</strong> through <strong>${r.i.histEnd}</strong>. Flexible success was <strong>${r.flex.toFixed(1)}%</strong>, full-target success <strong>${r.full.toFixed(1)}%</strong>, severe-shortfall risk <strong>${r.severeRisk.toFixed(1)}%</strong>, and depletion risk <strong>${r.depletion.toFixed(1)}%</strong>. The P10 minimum lifestyle funded was <strong>${p10Floor.toFixed(1)}%</strong> of the planned recurring target, while the bad-decile maximum annual lifestyle cut was about <strong>${money(p90Cut)}</strong> in today's dollars. Median after-tax ending value was <strong>${money(med)}</strong> (≈ ${money(medReal)} today); P10 was <strong>${money(p10)}</strong> (≈ ${money(p10Real)} today). Historical mode remains a sequence-risk stress test rather than a precise reconstruction of a Canadian household portfolio.`}else{text=`With these assumptions, the flexible plan funds its adjusted spending target in <strong>${r.flex.toFixed(1)}%</strong> of ${r.i.sims.toLocaleString()} paths, while <strong>${r.full.toFixed(1)}%</strong> maintain the full inflation-adjusted recurring target and fully fund any one-time purchase without a guardrail cut or shortfall. Severe lifestyle shortfall occurs in <strong>${r.severeRisk.toFixed(1)}%</strong> of paths and gross investable assets deplete before the horizon in <strong>${r.depletion.toFixed(1)}%</strong>. The P10 minimum lifestyle funded is <strong>${p10Floor.toFixed(1)}%</strong> of plan and the bad-decile largest annual cut is about <strong>${money(p90Cut)}</strong> in today's dollars. Median estimated after-tax liquidation value at Person A age ${r.i.planAge} is <strong>${money(med)}</strong> (≈ ${money(medReal)} today); P10 is <strong>${money(p10)}</strong> (≈ ${money(p10Real)} today). `;if(r.severeRisk<=2&&r.flex>=95)text+='The downside appears resilient under this model; the more useful next questions are spending capacity, tax sequencing, and legacy trade-offs.';else if(r.severeRisk<=10)text+='The plan looks workable but the adjustment rules matter. Review whether the modeled essential-spending floor matches your actual household necessities.';else text+='The downside magnitude is significant. Structural changes deserve testing before relying on the headline Monte Carlo success percentage.'}renderHistoricalTable(r);$('interpretation').innerHTML=text;}


