function reportDecisionSupportPage(){if(!lastDecisionSupport)return null;const {c,x}=newPdfPage();pageTitle(x,'Advanced Decision Support','Paired sensitivity screens using the same seed and path indices.');x.fillStyle='#0d2440';x.font='bold 21px Arial';x.fillText('Longevity sensitivity',58,165);x.fillStyle='#314b65';x.font='16px Arial';let y=198;for(const r of lastDecisionSupport.longevity){x.fillText(`Age ${r.age}: Full ${pct(r.full)} | Flexible ${pct(r.flex)} | Severe ${pct(r.severe)} | Depletion ${pct(r.depletion)} | P10 ${money(r.p10)} | Zone ${r.zone}`,70,y);y+=27;}y+=15;x.fillStyle='#0d2440';x.font='bold 21px Arial';x.fillText('Withdrawal strategies',58,y);y+=34;x.fillStyle='#314b65';x.font='16px Arial';for(const r of lastDecisionSupport.withdrawals){x.fillText(`${r.label}: Tax ${money(r.medianTax)} | P10 ${money(r.p10)} | Median ${money(r.p50)} | Severe ${pct(r.severe)} | Depletion ${pct(r.depletion)} | OAS claw ${pct(r.oasAny)}`,70,y);y+=27;}y+=15;x.fillStyle='#0d2440';x.font='bold 21px Arial';x.fillText('Major-purchase capacity',58,y);y+=34;x.fillStyle='#314b65';x.font='16px Arial';for(const r of lastDecisionSupport.purchase.rows){x.fillText(`${r.amount?money(r.amount):'Baseline'}: Full ${pct(r.full)} | Flexible ${pct(r.flex)} | Severe ${pct(r.severe)} | P10 ${money(r.p10)} | Max cut ${money(r.p90Cut)}`,70,y);y+=27;}if(lastDecisionSupport.purchase.affordable!==null){y+=12;x.font='bold 17px Arial';x.fillText(`Screened maximum affordable purchase: ${money(lastDecisionSupport.purchase.affordable)} at age ${lastDecisionSupport.purchase.age}`,70,y);}pageFooter(x);return c;}

