function shortMoney(v){if(!Number.isFinite(v)||Math.abs(v)<.5)return '—';const a=Math.abs(v),sign=v<0?'-':'';if(a>=1e6)return sign+'$'+(a/1e6).toFixed(a>=1e7?1:2)+'M';if(a>=1e3)return sign+'$'+(a/1e3).toFixed(a>=1e5?0:1)+'k';return sign+'$'+a.toFixed(0)}
