function reportRepSummaryPage(){const xsel=representativePaths?.[representativeActive];if(!xsel)return null;const p=xsel.path,rows=p.details||[],minGross=rows.length?Math.min(p.startingGross,...rows.map(z=>z.end.total)):p.startingGross,minRealGross=rows.length?Math.min(p.startingGross,...rows.map(z=>z.end.total/Math.max(.000001,z.cumInf))):p.startingGross,{c,x}=newPdfPage();pageTitle(x,`Representative Path - ${xsel.label}`,xsel.histYear!==null?`Historical retirement start ${xsel.histYear}`:`Monte Carlo path ${(xsel.index+1).toLocaleString()}`);const m=[['Starting investment',money(p.startingGross)],['Ending gross investment',money(p.endingGross)+' (≈ '+money(p.realEndingGross)+' today)'],['Ending after-tax liquidation',money(p.afterTax)+' (≈ '+money(p.realAfterTax)+' today)'],['Lifetime modeled tax',money(p.lifeTax)+' (≈ '+money(p.realLifeTax)+' today-$)'],['Retirement spending delivered',money(p.totalRetirementSpending)+' (≈ '+money(p.realRetirementSpending)+' today-$)'],['Lowest gross investment',money(minGross)+' (≈ '+money(minRealGross)+' today)']];for(let k=0;k<m.length;k++){const col=k%3,row=Math.floor(k/3);drawMetric(x,58+col*500,170+row*125,470,m[k][0],m[k][1],k===3?'#6547a6':'#0d2440')}x.fillStyle='#0d2440';x.font='bold 22px Arial';x.fillText('Cash-flow summary',58,470);x.fillStyle='#314b65';x.font='18px Arial';let yy=wrapCanvasText(x,$('repFlowSummary')?.innerText||'',58,505,1460,28);yy+=18;x.fillStyle='#0d2440';x.font='bold 22px Arial';x.fillText('How to read the ledger',58,yy);x.fillStyle='#314b65';x.font='17px Arial';wrapCanvasText(x,'A positive flow means money was added or reinvested into the account; a negative flow means money was withdrawn or sold. RRSP/RRIF combines both spouses and includes mandatory RRIF withdrawals. Tax is annual personal tax plus net modeled corporate investment tax/refunds. Ending after-tax liquidation includes the estimated tax cost of liquidating the remaining assets at the final planning horizon.',58,yy+35,1460,26);pageFooter(x);return c}
function reportLedgerPages(){const xsel=representativePaths?.[representativeActive],rows=xsel?.path?.details||[];if(!rows.length)return [];const headers=['Age','Year','Return','Start $','RRSP flow','RRSP end','TFSA flow','TFSA end','NR flow','NR end','Corp flow','Corp end','CPP/OAS','Passive','Tax','Spend','End $'],widths=[62,70,76,92,105,92,100,92,96,92,100,92,88,78,86,88,92],sum=widths.reduce((a,b)=>a+b,0),scale=1460/sum,w=widths.map(v=>v*scale),perPage=22,pages=[];for(let start=0;start<rows.length;start+=perPage){const {c,x}=newPdfPage(),chunk=rows.slice(start,start+perPage);pageTitle(x,`Representative Path Ledger - ${xsel.label}`,`Years ${start+1}-${start+chunk.length} of ${rows.length} • all dollar values nominal for that simulated year`);let sx=58,sy=170,rowH=42;x.fillStyle='#dfe9f2';x.fillRect(sx,sy,1460,rowH);x.fillStyle='#27445e';x.font='bold 11px Arial';let xx=sx;for(let j=0;j<headers.length;j++){x.fillText(headers[j],xx+3,sy+26);xx+=w[j]}for(let k=0;k<chunk.length;k++){const z=chunk[k],l=z.ledger||emptyYearLedger(),vals=[Math.round(z.ageA),z.calYear??'—',signedPct(z.portfolioReturn),shortMoney(z.start.total),flowPdf(l.rrspIn,l.rrspOut),shortMoney(z.end.rrsp),flowPdf(l.tfsaIn,l.tfsaOut),shortMoney(z.end.tfsa),flowPdf(l.nrIn,l.nrOut),shortMoney(z.end.nr),flowPdf(l.corpIn,l.corpOut),shortMoney(z.end.corp),shortMoney(z.cppOas),shortMoney(z.passiveCash),shortMoney(z.totalTax),z.spending===null?'—':shortMoney(z.spending),shortMoney(z.end.total)],y=sy+rowH*(k+1);x.fillStyle=k%2?'#fbfcfd':'#f4f7fa';x.fillRect(sx,y,1460,rowH);x.fillStyle='#2d465e';x.font='10px Arial';xx=sx;for(let j=0;j<vals.length;j++){x.fillText(cleanText(vals[j]),xx+3,y+26);xx+=w[j]}}pageFooter(x);pages.push(c)}return pages}
function exportFullReportPdf(){let preopened=null;const btn=$('exportReportBtn');const ios=isIOSLike();try{if(!lastSimulationResult)throw new Error('Run the simulation before exporting the full report.');
 // Keep desktop Chrome/Edge inside the original trusted click task. v4.0.2 yielded
 // with requestAnimationFrame/setTimeout before a.click(), which can cause a silent
 // download block for locally opened HTML files. iOS uses a pre-opened tab instead.
 if(ios){try{preopened=window.open('about:blank','_blank');if(preopened){preopened.document.title='Preparing Retirement Report';preopened.document.body.innerHTML='<div style="font-family:system-ui;padding:24px">Preparing retirement report…</div>';}}catch(e){preopened=null;}}
 if(btn){btn.disabled=true;btn.textContent='Building PDF…';}$('statusText').textContent='Building PDF report…';
 const pages=[reportSummaryPage(lastSimulationResult)];if(lastAllocationRows?.length)pages.push(reportAllocationPage(lastAllocationRows));const ds=reportDecisionSupportPage();if(ds)pages.push(ds);if($('fanChart'))pages.push(reportFanPage());if($('histChart')&&$('riskChart'))pages.push(reportOtherChartsPage());if(representativePaths){const rp=reportRepSummaryPage();if(rp)pages.push(rp);pages.push(...reportLedgerPages());}if(!pages.length)throw new Error('No completed report pages are available. Run the simulation again.');
 const blob=canvasesToPdfBlob(pages),date=new Date().toISOString().slice(0,10);savePdfBlob(blob,`Retirement_Decision_Report_${date}.pdf`,preopened);preopened=null;$('statusText').textContent=ios?'Report opened — use the PDF download/save control':'Report downloaded';
 }catch(e){console.error(e);if(preopened&&!preopened.closed)try{preopened.close()}catch(_){}$('statusText').textContent='PDF export error';alert('PDF export error: '+e.message);}finally{if(btn){btn.textContent='Export Full Report PDF';btn.disabled=!lastSimulationResult;updateReportExportState();}}}

document.getElementById('repPathTabs')?.addEventListener('click',(e)=>{const b=e.target.closest('.rep-tab');if(b&&b.dataset.rep)renderRepresentativePath(b.dataset.rep)});
async function startSimulation(){if($('autoSeed')?.checked){let seed=(Date.now()>>>0);try{const a=new Uint32Array(1);crypto.getRandomValues(a);seed=a[0]||seed}catch(e){}$('seed').value=seed;}$('seedHelp').textContent=$('autoSeed')?.checked?`Fresh random seed will be used each run. Current seed: ${$('seed').value}`:'Seed locked: repeated runs reproduce the same paths.';const i=readInputs(),errs=validate(i);if(errs.length){alert(errs.join('\n'));return}invalidateResults();$('statusText').textContent='Starting…';$('progressBar').style.width='1%';try{const r=await runSelectedSimulation(i);lastSimulationResult=r;render(r);$('statusText').textContent='Main simulation complete — comparing allocations…';$('progressBar').style.width='0%';const rows=await runAllocationComparison(i);lastAllocationRows=rows;renderAllocationComparison(rows,i.mode);$('statusText').textContent='Running focused decision support…';$('progressBar').style.width='0%';await runDecisionSupport(i);$('statusText').textContent='Complete — PDF report ready';$('progressBar').style.width='100%';updateReportExportState()}catch(e){console.error(e);$('statusText').textContent='Error';alert('Simulation error: '+e.message)}}
function loadDefaults(){location.reload()}
function bindUI(){
 const runBtn=$('runBtn'),resetBtn=$('resetBtn'),exportReportBtn=$('exportReportBtn'),tabInputs=$('tabInputs'),tabAdvanced=$('tabAdvanced'),tabMethod=$('tabMethod');
 if(runBtn)runBtn.addEventListener('click',startSimulation);
 if(resetBtn)resetBtn.addEventListener('click',loadDefaults);
 if(exportReportBtn)exportReportBtn.addEventListener('click',exportFullReportPdf);
 if($('addExpenseBtn'))$('addExpenseBtn').addEventListener('click',addExpenseItem);
 if($('generateSeedBtn'))$('generateSeedBtn').addEventListener('click',()=>{let seed=Date.now()>>>0;try{const a=new Uint32Array(1);crypto.getRandomValues(a);seed=a[0]||seed}catch(e){}$('seed').value=seed;$('autoSeed').checked=false;$('seedHelp').textContent='New seed generated and locked: '+seed;invalidateResults();});
 if($('expenseList')){ $('expenseList').addEventListener('click',e=>{const b=e.target.closest('[data-remove-expense]');if(b){v40Expenses.splice(Number(b.dataset.removeExpense),1);renderExpenseList();invalidateResults();}}); $('expenseList').addEventListener('change',e=>{const f=e.target.closest('[data-expense-field]');if(f)updateExpenseField(f);}); $('expenseList').addEventListener('input',e=>{const f=e.target.closest('[data-expense-field]');if(f&&['name','amount','start','end','interval','min','max','probability','endProbability','gap','maxOccurrences'].includes(f.dataset.expenseField))updateExpenseField(f);}); }
 if($('expenseResilienceBtn'))$('expenseResilienceBtn').addEventListener('click',async()=>{try{$('expenseResilienceResults').textContent='Running paired contingency stress…';await runExpenseResilience()}catch(e){alert(e.message)}});
 if($('saveDeviceBtn'))$('saveDeviceBtn').addEventListener('click',()=>{try{saveDevice()}catch(e){alert(e.message)}});
 if($('loadDeviceBtn'))$('loadDeviceBtn').addEventListener('click',()=>{try{loadDevice()}catch(e){alert(e.message)}});
 if($('exportPlanBtn'))$('exportPlanBtn').addEventListener('click',exportPlan);
 if($('exportBackupBtn'))$('exportBackupBtn').addEventListener('click',()=>{try{exportAllSaved()}catch(e){alert(e.message)}});
 if($('exportResultsCsvBtn'))$('exportResultsCsvBtn').addEventListener('click',()=>{try{exportResultsCsv()}catch(e){alert(e.message)}});
 if($('importPlanFile'))$('importPlanFile').addEventListener('change',async e=>{try{if(e.target.files[0])await importPlanFile(e.target.files[0])}catch(err){alert(err.message)}finally{e.target.value=''}});
 if($('saveScenarioBtn'))$('saveScenarioBtn').addEventListener('click',()=>{try{saveNamedScenario()}catch(e){alert(e.message)}});
 if($('compareScenariosBtn'))$('compareScenariosBtn').addEventListener('click',async()=>{try{await compareSavedScenarios()}catch(e){alert(e.message)}});
 if($('scenarioList'))$('scenarioList').addEventListener('click',e=>{const load=e.target.closest('[data-load-scenario]'),del=e.target.closest('[data-delete-scenario]'),d=v40ReadStore();if(load){const sc=(d.scenarios||[]).find(x=>x.id===load.dataset.loadScenario);if(sc)setFormPlan(sc.plan);}if(del){d.scenarios=(d.scenarios||[]).filter(x=>x.id!==del.dataset.deleteScenario);v40WriteStore(d);renderScenarioList();}});
 document.querySelectorAll('[data-chart-pdf]').forEach(b=>b.addEventListener('click',()=>exportChartPdf(b.dataset.chartPdf)));
 if(tabInputs)tabInputs.addEventListener('click',()=>showLeftTab('inputs'));
 if(tabAdvanced)tabAdvanced.addEventListener('click',()=>showLeftTab('advanced'));
 if(tabMethod)tabMethod.addEventListener('click',()=>showLeftTab('method'));
 const ios=/iPad|iPhone|iPod/.test(navigator.userAgent)||(navigator.platform==='MacIntel'&&navigator.maxTouchPoints>1);
 if(ios&&location.protocol==='file:'){const w=$('viewerWarning');if(w)w.classList.remove('hidden');}
 $('statusText').textContent='Ready — tap Run Simulation';
 $('progressBar').style.width='0%';renderExpenseList();renderScenarioList();updateReportExportState();
}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',bindUI,{once:true});else bindUI();
